function hhmm(s) { const m = String(s || '').match(/^(\d{1,2}):(\d{2})$/); return m ? Number(m[1]) * 60 + Number(m[2]) : 0; }

function htmlToText(h) { return String(h || '').replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li)>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n').trim(); }

function inSendWindow(ms, cfg) {
  const p = zonedParts(ms, cfg && cfg.tz);
  const mins = p.hh * 60 + p.mm;
  return p.dow >= 1 && p.dow <= 5 && mins >= hhmm(cfg && cfg.window_start) && mins < hhmm(cfg && cfg.window_end);
}

function isBrandOnlyFooter(foot) { const f = stripAcc(String(foot || '')).toLowerCase().replace(/[\s·|\-–—]+/g, ' ').trim(); return !f || f === 'atacama labs atacamalabs.cl' || f === 'atacamalabs.cl' || f === 'atacama labs'; }

function isValidEmail(e) { return /^[^\s@<>()",;:]+@[^\s@<>()",;:]+\.[a-z]{2,}$/i.test(normEmail(e)); }

function messageView(m) {
  return { id: m.id, company: m.company_name, kind: m.kind, direction: m.direction, status: m.status, to: m.to_email, subject: m.subject, classification: m.classification || null, at: m.sent_at || m.created_at, scheduled_for: m.scheduled_for || null, preview: String(m.body || '').slice(0, 280), thread: m.gmail_thread_id || null, error: m.error || null };
