  let score = 60;
  for (const r of rewards) score += r.pts;
  for (const w of warnings) score -= w.pts;
  score = Math.max(0, Math.min(100, Math.round(score)));
  const level = score >= 80 ? 'bueno' : score >= 65 ? 'aceptable' : 'bajo';
