  const dow = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[g('weekday')];
  return { y: Number(g('year')), m: Number(g('month')), d: Number(g('day')), hh: Number(g('hour')), mm: Number(g('minute')), dow, key: g('year') + '-' + g('month') + '-' + g('day') };
}

