  const words = cmWords(parts.text);
  const nWords = words.length;
  const list = Array.isArray(peers) ? peers.filter((p) => p && (p.body || p.subject)) : [];
  const c = cmNormCold(cold);
  const warnings = [], rewards = [], hard = [];
