  const pre = sw.slice(0, 3).join(' ');
  const sameSubj = list.filter((p) => cmNorm(p.subject) === sn).length;
  const samePre = sw.length >= 2 ? same(list, (p) => cmWords(p.subject).slice(0, 3).join(' ') === pre) : 0;
