  const sig = cmSignature(body);
  const sigRep = sig.split('>').length >= 4 ? same(list, (p) => cmSignature(p.body) === sig) : 0;
  if (sigRep >= 3) warn('misma_estructura', 'Tiene la misma estructura que ' + sigRep + ' correos recientes (' + sig.replace(/>/g, ' → ') + ').', 10);

